CREATE TABLE IF NOT EXISTS "public"."dcb_events_lite"
(
    "id"                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "data"              JSONB NOT NULL,
    "created_at"        timestamptz NOT NULL DEFAULT NOW()
) WITH (oids = false);

-- Version with sequence_number

CREATE TABLE IF NOT EXISTS "public"."dcb_flags_lite"
(
    "id"                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "database"          character varying(255) NOT NULL,
    "aggregate_name"    character varying(255) NOT NULL,
    "aggregate_id"      character varying(255) NOT NULL,
    "sequence_number"   integer NOT NULL,
    "event_id"          integer REFERENCES dcb_events_lite (id)
) WITH (oids = false);

CREATE UNIQUE INDEX "dcb_flags_lite_idx"
    ON "public"."dcb_flags_lite" ("database", "aggregate_name", "aggregate_id", "sequence_number");
